INSERT INTO `recipes` (`Id`, `Title`, `Description`, `Difficulty`, `TimeMinutes`, `Servings`, `IsExpensive`, `IsVegan`, `Type`, `DishPicture`, `CreatedAt`, `AuthorId`) VALUES
	(1, 'Mézes-fahéjas sült alma', 'A kedvenc almás receptem. Egyszerre nagyon könnyű, gyors, de ugyanakkor isteni finom és csak 5 hozzávalóra van szükséged.', 'Easy', 30, 3, 0, 0, 'Dessert', _binary , '2026-04-25 13:54:06.177834', 3);
INSERT INTO `recipes` (`Id`, `Title`, `Description`, `Difficulty`, `TimeMinutes`, `Servings`, `IsExpensive`, `IsVegan`, `Type`, `DishPicture`, `CreatedAt`, `AuthorId`) VALUES
	(2, 'Szegedi halászlé', 'Az igazi szegedi halászlé, szálkamentes ponttyal', 'Hard', 120, 10, 1, 0, 'MainDish', _binary , '2026-04-25 14:00:58.295821', 2),
	(3, 'Bableves', 'Bableves debreceni módra', 'Easy', 60, 1, 0, 0, 'MainDish', _binary , '2026-04-25 14:09:05.630665', 1);
INSERT INTO `recipesteps` (`Id`, `RecipeId`, `StepNumber`, `StepDescription`) VALUES
	(1, 1, 1, 'A sütőt előmelegítem 180 fokra.'),
	(2, 1, 2, 'Az almát megpucolom, majd az összeset félbe vágom és eltávolítom a magházat. Kb. 1 cm vastag szeletekre vágom és elkezdem kis szufflé tálkákba. A vajat és a mézet összeolvasztom és belekeverem a fahéjat, majd az egészet rálocsolom a rétegzett almára. 20–25 percig sütöm, amíg az alma kicsit megbarnul és összeesik.'),
	(3, 1, 3, 'A sült almára halmozzuk a tejszínhabot, melegen fogyasszuk.'),
	(4, 2, 1, 'Az igazi szegedi halászlé elkészítéséhez megpucoljuk a pontyot, kifilézzük, részeire szedjük, a keserű fogat eltávolítva belőle.'),
	(5, 2, 2, 'A hagymát megpucoljuk és felszeleteljük, a tölteni való paprikát kicsumázzuk, a paradicsomot felnegyedeljük, a fokhagymát keresztben kettévágjuk.'),
	(6, 2, 3, 'A halalapléhez félretett halat és az előkészített zöldségeket feltesszük főni 8 liter vízben és erős lángon 1 órát főzzük. Amikor felforrt, a fűszerpaprikát a leves tetején lévő zsírra szórjuk, amely sűríteni fogja azt. '),
	(7, 2, 4, 'Átpasszírozzuk a levest, majd visszatesszük a lángra és hozzáadjuk a leveskockákat és megsózzuk. Amint ezek felolvadtak a leves hagyhatjuk kihűlni és felhasználásig hűtőbe tehetjük.'),
	(8, 2, 5, 'Befejezéskor egyszerűen a halat beletesszük, felforraljuk és lobogva 6 percig főzzük. Hegyes erőset és friss kenyeret kínáljunk hozzá.'),
	(9, 3, 1, 'A debreceni bableveshez a répákat és a zellert felkockázzuk és egy kevés olajon átpirítjuk, hozzáadjuk a felkarikázott hagymát és üvegesre pároljuk. Ezután felöntjük kb. 1,5-2 l vízzel, megsózzuk, hozzáadjuk a babérlevelet, és főzni kezdjük.'),
	(10, 3, 2, 'A kolbászt felkarikázzuk, és egy serpenyőben a zsírjára pirítjuk, majd egy szűrőkanállal kiszedjük és beletesszük a levesbe.'),
	(11, 3, 3, 'A tojásból, a lisztből és a sóból csipetketésztát gyúrunk, majd a levesbe csipkedjük.'),
	(12, 3, 4, 'A kolbász visszamaradt zsírjában megpirítjuk a lisztet, hozzáadjuk a pirospaprikát, a zúzott fokhagymát és több részletben felengedjük összesen 1,5 dl vízzel. Ezután az elkészült rántással besűrítjük a levest.'),
	(13, 3, 5, 'A tejfölt pár kanál forró leveslével kikeverjük, majd hozzáöntjük a leveshez és jól összeforraljuk. Végül - ha szükséges - sóval ízesítjük és megszórjuk aprított petrezselyemmel.');
INSERT INTO `reviews` (`Id`, `RecipeId`, `UserId`, `Stars`, `Comment`, `CreatedAt`, `UpdatedAt`) VALUES
	(1, 1, 1, 5, 'Gyors, egyszerű, de mégis különleges!  Egyszerűen ellenállhatatlan!', '2026-04-25 16:10:59.935416', NULL),
	(2, 2, 3, 5, 'Autentikus szegedi recept, a ponty és a fűszerpaprikás alaplé kombója verhetetlen. Igazi klasszikus!', '2026-04-25 16:13:07.135030', NULL),
	(3, 3, 2, 5, 'Laktató, fűszeres, igazi magyar íz! Hideg napokra fantasztikus!', '2026-04-25 16:15:00.269086', NULL);
INSERT INTO `users` (`Id`, `FullName`, `Email`, `PasswordHash`, `Bio`, `ProfilePicture`, `Rank`) VALUES
	(1, 'Debrecen', 'debrecen@recepttar.hu', '0fadf52a4580cfebb99e61162139af3d3a6403c1d36b83e4962b721d1c8cbd0b', 'Ha nem kolbász, akkor mi? Debrecenből jelentkezem, és az itteni konyha az egyetlen igaz út.', _binary , 'FoodLegend');
INSERT INTO `users` (`Id`, `FullName`, `Email`, `PasswordHash`, `Bio`, `ProfilePicture`, `Rank`) VALUES
	(2, 'Szeged', 'szeged@recepttar.hu', '0fadf52a4580cfebb99e61162139af3d3a6403c1d36b83e4962b721d1c8cbd0b', 'A Tisza partján nőttem fel. A halászlé nem recept, hanem életforma.', _binary , 'FoodLegend'),
	(3, 'Kecskemét', 'kecskemet@recepttar.hu', '0fadf52a4580cfebb99e61162139af3d3a6403c1d36b83e4962b721d1c8cbd0b', 'Barackpálinka, baracklekvár, barackgombóc. Kecskemét a világ közepe.', _binary , 'FoodLegend');
